    toolsCtx.effect(() => {
      const mode: 'eager' | 'on-demand' = config.agentToolLoading === 'on-demand' ? 'on-demand' : 'eager'
      const disposers: Array<() => void> = []
      let surface: AgentSurfaceControl | undefined

      /**
       * 托管行（`buildServersDto` 是唯一读取逻辑：卡片、路由、两个工具与装载白名单共用它）。
