      const serverRows = (): Array<Record<string, unknown>> => {
        try {
          return buildServersDto(toolsCtx).servers
        } catch {
          return []
        }
      }
      /** 可装载的 server 名（顺序 = 托管行顺序）。 */
      const serverNames = (): string[] => {
        const names: string[] = []
