      "content": "{\n  \"name\": \"@hyzyn/dsh-mcp\",\n  \"version\": \"0.3.13\",\n  \"description\": \"DSH Web GUI 的 MCP 服务器配置插件：托管 ~/.dsh/cordis.patch.yml 的 MCP 区块，支持 stdio / streamable-http、连接测试与启用停用，保存后经 HMR 热加载为 mcp__<server>__<tool> 工具。\",\n  \"type\": \"module\",\n  \"engines\": {\n    \"node\": \">=22.19.0\"\n  },\n  \"main\": \"lib/index.js\",\n  \"types\": \"lib/index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./client\": \"./client.js\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"dsh\": {\n    \"manifestVersion\": 1,\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"engines\": {\n      \"dsh\": \">=0.1.7-rc.2\"\n    },\n    \"client\": {\n      \"platform\": \"web\",\n      \"inject\": []\n    }\n  },\n  \"dependencies\": {\n    \"@deepseek-ai/schemastery\": \"^3.18.4\",\n    \"@hyzyn/dsh-kit\": \"0.8.0\",\n    \"js-yaml\": \"^4.1.0\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/dsh\": \"^0.1.7-rc.2 || ^0.2.0-rc.1 || ^0.2.0-rc.2 || ^0.2.1-alpha.1 || ^0.2.1-alpha.2 || ^0.2.1-alpha.5 || ^0.2.1-rc.1 || ^0.2.1-rc.2 || ^0.2.1-rc.3 || ^0.2.1-rc.4 || ^0.2.1-rc.5 || ^0.2.2-alpha.3 || ^0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-tools\": \"^0.1.7-rc.2 || ^0.2.0-rc.1 || ^0.2.0-rc.2 || ^0.2.1-alpha.1 || ^0.2.1-alpha.2 || ^0.2.1-alpha.5 || ^0.2.1-rc.1 || ^0.2.1-rc.2 || ^0.2.1-rc.3 || ^0.2.1-rc.4 || ^0.2.1-rc.5 || ^0.2.2-alpha.3 || ^0.2.2-rc.1\",\n    \"react\": \"^18.2.0\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.4\",\n    \"@deepseek-ai/dsh-tools\": \"0.1.2-rc.1\",\n    \"@types/node\": \"^22.20.0\",\n    \"react\": \"^18.2.0\",\n    \"typescript\": \"~5.9.3\"\n  },\n  \"scripts\": {\n    \"build\": \"tsc -p tsconfig.json\",\n    \"typecheck\": \"tsc --noEmit && node ../../scripts/client-lint.mjs\",\n    \"lint:client\": \"node ../../scripts/client-lint.mjs\",\n    \"http-smoke\": \"node ../../scripts/verify-mcp