    {
      "path": "packages/mcp/client.js",
      "content": "/* eslint-disable */\n/**\n * @hyzyn/dsh-mcp — 浏览器半体：官方插件配置里的「MCP 服务器配置」卡片。\n * 通过核心 slots 服务注册到 settings.plugin.item 插槽（与官方终端 / Agent 循环 /\n * 网页搜索卡片同级），不再占用侧边栏、不做全屏面板接管。\n * 纯 DOM 渲染（React 只承担卡片外壳与展开状态），无构建步骤，\n * 宿主经 /plugins/@hyzyn/dsh-mcp/client.js 提供。\n */\nwindow.__ModuleLoader__.load({\n  id: '@hyzyn/dsh-mcp',\n  factory: (require) => {\n    const exports = {}\n\n    const React = require('react')\n    const { jsx, jsxs } = require('react/jsx-runtime')\n\n    /* ================================ CSS ================================ */\n\n    const CSS = [\n      // 设置插件卡片外壳（与官方 PluginCard 一致的轮廓）\n      '.mX_pageHost{display:block}',\n      '.mX_pluginCard{list-style:none;border:.5px solid var(--dsw-alias-settings-card-stroke);background:var(--dsw-alias-settings-card-fill);border-radius:var(--dsw-radius-xl);transition:border-color .16s,background .16s}',\n      '.mX_pluginCard:hover{border-color:var(--dsw-alias-label-dimmed)}',\n      '.mX_pluginCardOpen{background:var(--dsw-alias-bg-layer-1);border-color:var(--dsw-alias-label-dimmed)}',\n      '.mX_cardHeader{appearance:none;width:100%;color:inherit;font:inherit;text-align:left;cursor:pointer;background:0 0;border:0;border-radius:var(--dsw-radius-xl);display:flex;align-items:center;gap:12px;padding:14px 16px}',\n      '.mX_cardHeader:focus-visible{outline:var(--dsw-focus-ring-width) solid var(--dsw-focus-ring-color,var(--dsw-alias-state-business-primary));outline-offset:-2px}',\n      '.mX_cardHeadText{flex:1;min-width:0;display:flex;flex-direction:column;gap:3px}',\n      // 卡片标题：本文件另有一条 .mX_cardName（面板内实体名）——同选择器后者整条覆盖前者，\n      // 那两条 14px/600 与 13.5px/700 都是死声明；合并为官方 cardTitle 角色 14px/500/22px。\n      '.mX_cardName{color:var(--dsw-alias-label-primary);font-size:14px;font-weight:500;line-height:22px}',\n      '.dshkit_badge{flex:none;margin-left:auto;padding:1px 8px;border-radius:999px;corner-shape:round;font-size:11px;font-weight:600;line-height:16px;letter-spacing:.02em;color:var(--dsw-