ex:1;min-width:0}',\n      '.mX_cardActions{display:flex;align-items:center;gap:10px;margin-left:auto}',\n      // 卡片内的问题行（目前只有「已挂载但没连上」一种）：与摘要之间加一道分隔，\n      // 文字保持次要色（长句用警告色会吵），靠徽标与左边的停用按钮传达该干什么。\n      '.mX_badge{display:inline-block;border:.5px solid var(--dsw-alias-border-l2);color:var(--dsw-alias-label-secondary);border-radius:999px;corner-shape:round;padding:1px 8px;font-size:11px;line-height:16px;white-space:nowrap}',\n      '.mX_badge[data-kind=stdio]{color:var(--dsw-alias-state-business-primary);border-color:var(--dsw-alias-state-business-primary)}',\n      '.mX_badge[data-kind=http]{color:var(--dsw-alias-state-business-primary);border-color:var(--dsw-alias-state-business-primary)}',\n      '.mX_badge[data-status=ok]{color:var(--dsw-alias-state-success-primary);border-color:var(--dsw-alias-state-success-primary)}',\n      '.mX_badge[data-status=error]{color:var(--dsw-alias-state-error-primary);border-color:var(--dsw-alias-state-error-primary)}',\n      '.mX_badge[data-status=warn]{color:var(--dsw-alias-state-warn-primary);border-color:var(--dsw-alias-state-warn-primary)}',\n      '.mX_banner{border:.5px solid var(--dsw-alias-border-l2);color:var(--dsw-alias-label-secondary);border-radius:8px;padding:8px 12px;font-size:12.5px;line-height:18px;overflow-wrap:anywhere;flex:none}',\n      '.mX_banner[data-kind=ok]{color:var(--dsw-alias-state-success-primary);border-color:var(--dsw-alias-state-success-primary)}',\n      '.mX_banner[data-kind=error]{color:var(--dsw-alias-state-error-primary);border-color:var(--dsw-alias-state-error-primary)}',\n      '.mX_banner[data-kind=info]{color:var(--dsw-alias-state-business-primary);border-color:var(--dsw-alias-state-business-primary)}',\n      '.mX_banner[data-kind=warn]{color:var(--dsw-alias-state-warn-primary);border-color:var(--dsw-alias-state-warn-primary)}',\n      // 「外部占用」是**信息**、不是告警：做成列表下方的紧凑脚注（一行小字 + 名字 chip），\n      // 尺寸与位置都与真冲突的黄色横幅（.mX_banner[data-kind=warn]）明显拉开。\n      '.mX_note{display:flex;align-items:center;flex-wrap:wrap;gap:6px;flex:none;background:var(--dsw-alias-bg-layer-2);border:.5px solid var(--dsw-alias-border-l1);border-radius:8px;padding:6px 10px;font-size:12px;line-height:18px;color:var(--dsw-alias-label-tertiary)}',\n      '.mX_noteGlyph{flex:none;width:13px;height:13px;border-radius:50%;corner-shape:round;border:1px solid var(--dsw-alias-state-business-primary);color:var(--dsw-alias-state-business-primary);font-size:9px;font-weight:600;font-style:normal;line-height:11px;text-align:center}',\n      '.mX_noteName{font-family:var(--ds-font-family-code);font-size:11px;line-height:16px;color:var(--dsw-alias-label-secondary);background:var(--dsw-alias-bg-layer-3);border:.5px solid var(--dsw-alias-border-l2);border-radius:var(--dsw-radius-sm);padding:0 6px}',\n      '.mX_empty,.mX_loading{text-align:center;color:var(--dsw-alias-label-tertiary);padding:24px 12px;font-size:12.5px;line-height:18px}',\n      '.mX_modalBackdrop{position:absolute;inset:0;z-index:70;background:var(--dsw-alias-bg-mask-1);display:flex;justify-content:center;align-items:flex-start;padding:24px 12px;overflow-y:auto}',\n      '.mX_modal{background:var(--dsw-alias-bg-base);border:0;width:min(640px,100%);max-width:100%;box-shadow:var(--dsw-elevation-prominent);color:var(--dsw-alias-label-primary);border-radius:var(--dsw-radius-lg);display:flex;flex-direction:column;gap:12px;padding:18px;box-sizing:border-box}',\n      '.mX_modalTitle{margin:0;font-size:15px;font-weight:600;line-height:22px}',\n      '.mX_modalBody{display:flex;flex-direction:column;gap:10px}',\n      '.mX_modalFooter{display:flex;justify-content:flex-end;align-items:center;gap:10px;margin-top:4px}',\n      '.mX_formRow{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px 12px}',\n      '.mX_field{display:flex;flex-direction:column;gap:5px}',\n      '.mX_fieldLabel{color:var(--dsw-alias-label-secondary);font-size:12px;font-weight:500;line-height:18px}',\n      // 输入档对齐宿主 settings-form 的 .input：显式 H34 + --dsw-radius-md（原来靠 7px 10px 撑高、\n      // 圆角写死 8px）。高度必须显式：<select> 复用同一个类时 Chrome 不算继承的 line-height\n      // （内容高实测 16px），没有高度就会比同排输入框矮 2px；textarea 由下面的 .mX_textarea 覆盖回 auto。\n      '.mX_input{box-sizing:border-box;width:100%;height:34px;padding:0 12px;color:var(--dsw-alias-label-primary);background:var(--dsw-alias-bg-layer-3);border:.5px solid var(--dsw-alias-border-l4);border-radius:var(--dsw-radius-md);outline:none;font-family:inherit;font-size:13px;line-height:1.5}',\n      '.mX_input:focus{border-color:var(--dsw-alias-state-business-primary)}',\n      '.mX_input::placeholder{color:var(--dsw-alias-label-dimmed)}',\n      // 多行 textarea 不吃输入档的 H34（官方：textarea 用 height:auto + min-height）与横向内边距。\n      '.mX_textarea{height:auto;min-height:64px;padding:8px 12px;resize:vertical;font-family:var(--ds-font-family-code);font-size:12px;line-height:18px}',\n      '.mX_hint{color:var(--dsw-alias-label-tertiary);font-size:12px;line-height:18px}',\n      // 字段级实时校验（serverName 撞名）：必须排在 `.mX_input:focus` **之后**，\n      // 否则聚焦时那抹主题蓝会盖掉标红（两条选择器权重相同，比的是顺序）。\n      '.mX_input[data-invalid]{border-color:var(--dsw-alias-state-error-primary)}',\n      '.mX_fieldError{color:var(--dsw-alias-state-error-primary);font-size:12px;line-height:18px;margin:0;white-space:pre-wrap}',\n      '.mX_fieldError:empty{display:none}',\n      '.mX_radioRow{display:flex;align-items:center;gap:16px}',\n      '.mX_radioLabel{display:inline-flex;align-items:center;gap:6px;font-size:13px;line-height:20px;cursor:pointer;color:var(--dsw-alias-label-primary)}',\n      '.mX_checkRow{display:flex;align-items:center;gap:8px;font-size:13px;line-height:20px;color:var(--dsw-alias-label-primary);cursor:pointer}',\n      // 原生复选框按宿主 Checkbox 写：16×16 + accent-color 走中性 brand（浅色近黑）。\n      // 用强调蓝 state-business-primary（#4176e6）就是浏览器默认蓝勾那种错——那是状态与徽标的颜色。\n      '.mX_checkRow input[type=checkbox]{width:16px;height:16px;margin:0;flex:none;cursor:pointer;accent-color:var(--dsw-alias-brand-primary)}',\n      '.mX_checkRow input[type=checkbox]:focus-visible{outline:var(--dsw-focus-ring-width) solid var(--dsw-focus-ring-color,var(--dsw-alias-state-business-primary));outline-offset:2px}',\n      // 该行贡献的工具数：**成本**信息（次级色，与传输/运行中/冲突那些徽标同一行）。\n      // 不并进徽标族——本卡的徽标是「状态」语义，工具数是「这一行要付多少常驻上下文」。\n      '.mX_metaRow{display:flex;align-items:center;gap:10px;flex-wrap:wrap}',\n      '.mX_toolCount{color:var(--dsw-alias-label-tertiary);font-size:12px;line-height:18px;font-family:var(--ds-font-family-code)}',\n      '.mX_formError{color:var(--dsw-alias-state-error-primary);font-size:12px;line-height:18px;margin:0;white-space:pre-wrap}',\n      '.mX_toolWrap{border:.5px solid var(--dsw-alias-border-l1);border-radius:var(--dsw-radius-md);flex:none;overflow:hidden}',\n      // 试连结果槽：没有结果时是空的，:empty 把节点整个摘出布局——否则它会以 flex gap 的形式\n      // 在列表和底栏之间多留 12px（每次打开面板都看得见）。\n      '.mX_testPanel:empty{display:none}',\n      '.mX_toolHeader{background:var(--dsw-alias-bg-layer-2);border-bottom:.5px solid var(--dsw-alias-border-l1);padding:8px 10px;font-size:12px;line-height:18px;color:var(--dsw-alias-label-secondary);display:flex;gap:12px;flex-wrap:wrap}',\n      '.mX_toolList{max-height:220px;overflow-y:auto;padding:4px 0}',\n      '.mX_toolItem{padding:5px 10px;font-size:12px;line-height:18px;display:flex;flex-direction:column;gap:2px;border-bottom:.5px solid var(--dsw-alias-border-l2)}',\n      '.mX_toolItem:last-child{border-bottom:none}',\n      '.mX_toolName{font-family:var(--ds-font-family-code);color:var(--dsw-alias-state-business-primary)}',\n      '.mX_toolDesc{color:var(--dsw-alias-label-tertiary)}',\n      '.mX_spinner{border:2px solid var(--dsw-alias-state-business-primary);border-top-color:transparent;border-radius:50%;corner-shape:round;width:11px;height:11px;display:inline-block;flex:none;vertical-align:-1px;animation:mXSpin .8s linear infinite}',\n      '@keyframes mXSpin{to{transform:rotate(360deg)}}',\n      '.mX_toast{position:fixed;left:50%;bottom:36px;transform:translateX(-50%);z-index:200;background:var(--dsw-alias-bg-layer-2);border:0;color:var(--dsw-alias-label-primary);border-radius:var(--dsw-radius-md);padding:9px 16px;font-size:13px;line-height:20px;box-shadow:var(--dsw-elevation-prominent);max-width:70vw}',\n      '.mX_toast[data-kind=ok]{color:var(--dsw-alias-state-success-primary);box-shadow:var(--dsw-elevation-prominent), inset 0 0 0 .5px var(--dsw-alias-state-success-primary)}',\n      '.mX_toast[data-kind=error]{color:var(--dsw-alias-state-error-primary);box-shadow:var(--dsw-elevation-prominent), inset 0 0 0 .5px var(--dsw-alias-state-error-primary)}',\n      // 宿主给的 warning（例如「宿主没有 settings 服务：改动只在本次进程内有效」）走第三档：\n      // 它不是错误（这次改动生效了），也不是成功（重启后会丢），所以复用告警色而不是红或绿。\n      '.mX_toast[data-kind=warn]{color:var(--dsw-alias-state-warn-primary);box-shadow:var(--dsw-elevation-prominent), inset 0 0 0 .5px var(--dsw-alias-state-warn-primary)}',\n      '.mX_mono{font-family:var(--ds-font-family-code)}',\n    ].join('\\n')\n\n    let styleEl\n    function ensureStyle() {\n      if (document.getElementById('dsh-mcp-style')) return\n      styleEl = document.createElement('style')\n      styleEl.id = 'dsh-mcp-style'\n      styleEl.textContent = CSS\n      document.head.appendChild(styleEl)\n    }\n\n    /* ================================ 基础工具 ================================ */\n\n    const ESC_MAP = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }\n    const esc = (value) => String(value ?? '').replace(/[&<>\"']/g, (c) => ESC_MAP[c])\n\n    /* ================================ 国际化 ================================ */\n\n    /*\n     * 界面文案走宿主 `@deepseek-ai/dsh-client-locale` 的目录（方案见 docs/i18n.md）。\n     * 下面这一对目录由 `scripts/check-i18n.mjs` 静态校验：键集必须与英文一一对应、\n     * `{name}` 占位符两边一致、代码里 `t('…')` 用到的键必须在这里有定义。\n     * 目录**内联在 client.js 里**（不是 client-src/）：本包没有构建步骤，client.js 就是源；\n     * 而且一旦凭空建出 client-src/，仓库级「宿主地址来源」静态规则会停止覆盖 client.js。\n     *\n     * 面板 DOM 是**手写 HTML 字符串**拼的，所以带 `<` / `&` 的文案一律用 `esc(t(...))`\n  