firmRemove': '确定删除 MCP 服务器「{name}」？其注册的工具会立即被卸载。',\n    }\n    const I18N_EN = {\n      'card.name': 'MCP server configuration',\n      'card.desc': 'Manage MCP servers: stdio local processes or streamable-http remote services; saving hot-loads them as mcp__<server>__<tool> tools — no restart needed.',\n      'panel.title': 'MCP servers',\n      'btn.refresh': 'Refresh',\n      'btn.addServer': '+ Add server',\n      'btn.test': 'Test',\n      'btn.edit': 'Edit',\n      'btn.enable': 'Enable',\n      'btn.disable': 'Disable',\n      'btn.remove': 'Remove',\n      'btn.cancel': 'Cancel',\n      'btn.testConnection': 'Test connection',\n      'btn.save': 'Save',\n      'list.statusActive': 'Running',\n      'list.notConnected': 'Not connected',\n      'list.statusDisabled': 'Disabled',\n      'list.statusError': 'Error',\n      'list.statusLoading': 'Loading',\n      'list.statusNotLoaded': 'Not loaded',\n      'list.conflict': 'serverName conflict',\n      'list.toolsCount': '{count} tools',\n      'list.toolsUnknown': 'tool count unknown',\n      'list.toolsCountHint': 'How many tools this server currently has in the tool registry (the host DTO’s toolCount). “Unknown” means the host cannot read the registry — that is not 0.',\n      'list.agentBudget': 'MCP tools add up to {total}, past the {budget} line: they ride along in every request. Disable a few rows you do not need — a disabled row registers no tools, so it stops costing anything.',\n      'panel.editorCreate': 'Add MCP server',\n      'panel.editorEdit': 'Edit MCP server',\n      'panel.fieldName': 'serverName (model-side namespace, [A-Za-z0-9_-], 1–32 chars)',\n      'placeholder.serverName': 'e.g. github',\n      'panel.fieldTransport': 'Transport',\n      'panel.transportStdio': ' stdio (local process)',\n      'panel.transportHttp': ' streamable-http (remote)',\n      'panel.fieldCommand': 'command (executable)',\n      'panel.fieldCwd': 'cwd (working directory, optional; the directory must already exist)',\n      'panel.fieldArgs': 'args (JSON array, or one argument per line)',\n      'panel.fieldEnv': 'env (KEY=VALUE per line; a js: prefix is a JS expression)',\n      'panel.fieldUrl': 'url (MCP endpoint)',\n      'panel.fieldHeaders': 'headers (KEY=VALUE per line; a js: prefix is a JS expression, templates may reference env vars)',\n      'panel.fieldFailOnStartupError': ' failOnStartupError (refuse to load when startup fails)',\n      'panel.fieldEnabled': ' Enabled',\n      'panel.fieldReconnect': ' Reconnect automatically after a drop',\n      'panel.hint': 'An env/headers VALUE starting with js: is written as a !!js expression verbatim (e.g. js:process.env.GITHUB_TOKEN). Saving hot-loads the server; tool names look like mcp__<serverName>__<tool>.',\n      'banner.fileError': 'Malformed configuration block: {error} (saving once repairs it)',\n      'banner.conflicts': '⚠ These serverNames clash with mcp-client instances outside this plugin — both would claim the same tool names mcp__<serverName>__*, and one of them is bound to fail loading: {names}',\n      'banner.externalOccupied': 'Already taken by mcp-client instances outside this card — avoid these names here:',\n      'banner.externalOccupiedHint': 'These rows are managed by other plugins (they live outside this card’s managed block), so this card cannot change them. A same-named server would make two mcp-client instances claim the same mcp__<serverName>__* tool names and one of them is bound to fail loading; rename it in that plugin’s settings instead.',\n      'msg.hotReload': 'Changes are written to the managed block of ~/.dsh/cordis.patch.yml and hot-loaded via HMR (effective in about 1–2 seconds). An env/headers value starting with js: is treated as a !!js expression (e.g. js:process.env.GITHUB_TOKEN).',\n      'msg.testConnecting': 'Connecting and listing tools… (up to 25 seconds)',\n      'msg.testOk': 'Connected',\n      'msg.testFailed': 'Connection failed: {error}',\n      'msg.metaDuration': 'took {ms}ms',\n      'msg.metaProtocol': 'protocol {version}',\n      'msg.metaServer': 'server {name}',\n      'msg.metaTools': '{count} tools',\n      'list.loading': 'Loading…',\n      'list.empty': 'No MCP servers configured yet.',\n      'list.emptyHint': 'Click “+ Add server” in the top right to start: both stdio local processes and streamable-http services are supported.',\n      'list.emptyReload': 'After saving, DSH hot-loads it as mcp__<serverName>__<tool> tools — no restart needed.',\n      'list.separator': ', ',\n      'error.unknown': 'unknown error',\n      'error.argsNotArray': 'args must be a JSON array of strings',\n      'error.unparsableLine': 'Unparsable line: {line}',\n      'error.duplicateName': 'serverName already exists: {name}',\n      'error.externalClash': 'serverName “{name}” is already taken by an mcp-client instance outside this plugin ({id}): the two instances would fight over the same tool names and one of them is bound to fail loading. That row is managed by another plugin — change it in that plugin’s settings.',\n      'msg.saveFailed': 'Could not save: {error}',\n      'msg.removeFailed': 'Could not remove: {error}',\n      'msg.updateFailed': 'Could not update: {error}',\n      'msg.saved': 'Saved, hot-loading…',\n      'msg.deleted': 'Removed, hot-unloading…',\n      'msg.updated': 'Updated, hot-loading…',\n      'msg.testOkHint': 'Connected (click Save once it looks right)',\n      'msg.testFailedToast': 'Connection failed',\n      'msg.confirmRemoveLast': 'Remove the last MCP server “{name}”? The managed block will be emptied and its tools unloaded immediately.',\n      'msg.confirmRemove': 'Remove MCP server “{name}”? Its tools will be unloaded immediately.',\n    }\n    /* ==== dsh-i18n:end ==== */\n\n    /** 占位符替换：`{name}` → params.name（缺参留空，不抛错——文案不该打死界面）。 */\n    function i18nFormat(text, params) {\n      if (params === undefined) return text\n      return String(text).replace(/\\{(\\w+)\\}/g, (_match, name) => (params[name] === undefined ? '' : String(params[name])))\n    }\n\n    /** 中文兜底：老宿主（DSH ≤0.1.5）没有 locale 服务时，界面不能变成一串键名。 */\n    function i18nFallback(key, params) {\n      return i18nFormat(I18N_ZH[key] !== undefined ? I18N_ZH[key] : key, params)\n    }\n\n    let t = i18nFallback\n\n    /**\n     * 注册目录并绑定翻译函数。**动态 inject**：老宿主上回调永不触发、`t` 保持中文兜底；\n     * 写成静态 `inject: ['locale']` 会让整张卡片在老宿主上根本不挂。\n     */\n    function installI18n(ctx) {\n      ctx.inject(['locale'], (i18nCtx) => {\n        const disposeZh = i18nCtx.locale.register(I18N_NS, 'zh', I18N_ZH)\n        const disposeEn = i18nCtx.locale.register(I18N_NS, 'en', I18N_EN)\n        t = i18nCtx.locale.bind(I18N_NS)\n        return () => {\n          disposeEn()\n          disposeZh()\n          t = i18nFallback\n        }\n      })\n    }\n\n    /* ================================ API ================================ */\n\n    const API = {\n      list: '/api/dsh-mcp/servers',\n      save: '/api/dsh-mcp/servers/save',\n      test: '/api/dsh-mcp/test',\n    }\n\n    async function apiRequest(path, options) {\n      const res = await fetch(path, options)\n      let body = {}\n      try {\n        body = await res.json()\n      } catch {\n        /* 非 JSON 响应 */\n      }\n      if (!res.ok) {\n        const err = new Error((body && body.error) || ('HTTP ' + res.status))\n        err.code = res.status\n        throw err\n      }\n      return body\n    }\n\n    const apiList = () => apiRequest(API.list)\n    /*\n     * `options.clearAll` 是**显式信号**：只在「用户明确删光」时带上。宿主对「空列表且无该标记」\n     * 的保存会返回 400，避免启动竞态 / 陈旧卡片拿到空列表时把已配置的服务器静默清空。\n     */\n    const apiSave = (servers, options) => {\n      const opts = options !== undefined ? options : {}\n      return apiRequest(API.save, {\n        method: 'POST',\n        headers: { 'content-type': 'application/json' },\n        body: JSON.stringify({\n          servers,\n          ...(opts.clearAll === true ? { clearAll: true } : {}),\n        }),\n      })\n    }\n    const apiTest = (config) => apiRequest(API.test, {\n      method: 'POST',\n      headers: { 'content-type': 'application/json' },\n      body: JSON.stringify({ config }),\n    })\n\n    /* ================================ 面板状态 ================================ */\n\n    const state = {\n      servers: [],\n      // 真正重名的托管行（横幅只渲染这份）；外部实例清单另存 externalServers，两者别混用。\n      conflicts: [],\n      externalServers: [],\n      // 宿主下发的成本阈值（DTO 的 toolBudget）；老宿主没有这个字段 → null → 不提示。\n      toolBudget: null,\n      // 正在等宿主把 patch 热加载完（见 reloadUntilSettled）：这段时间徽标按**期望态**渲染。\n      settling: false,\n      fileError: '',\n      patchFile: '',\n      loading: false,\n      busy: false,\n      toast: '',\n      toastKind: 'info',\n      editor: null,\n      test: null,\n    }\n\n    let toastTimer\n    function toast(message, kind) {\n      state.toast = message\n      state.toastKind = kind || 'info'\n      renderToast()\n      clearTimeout(toastTimer)\n      toastTimer = setTimeout(() => {\n        state.toast = ''\n        renderToast()\n      }, 3200)\n    }\n\n    /**\n     * 保存类请求的统一收尾：**宿主给的 warning 优先**。\n     *\n     * 它说的是「宿主没有 settings 服务，改动只在本次进程内有效」这类比「已保存」重要得多的事实；\n     * 被后一条 toast 顶掉等于没说（toast 只有一条）。\n     */\n    function notifySaved(body, message) {\n      const warning = body !== undefined && body !== null ? body.warning : undefined\n      if (typeof warning === 'string' && warning !== '') toast(warning, 'warn')\n      else toast(message, 'ok')\n    }\n\n    /* ================================ 渲染：主视图 ================================ */\n\n    /*\n     * 状态文案**必须走 getter**：`t()` 在模块加载时求值等于把当前语言冻住——\n     * `installI18n(ctx)` 要等 apply 才跑（那时已经晚了），语言切换后这里会永远停在\n     * 首次求值的结果上。\n     */\n    const STATUS_TEXT = {\n      get active() { return t('list.statusActive') },\n      get disabled() { return t('list.statusDisabled') },\n      get error() { return t('list.statusError') },\n      get loading() { return t('list.statusLoading') },\n      get 'not-loaded'() { return t('list.statusNotLoaded') },\n    }\n    const STATUS_KIND = { active: 'ok', disabled: '', error: 'error', loading: 'warn', 'not-loaded': '' }\n\n    let panelEl\n    let toastEl\n\n    /*\n     * 上一次渲染出去的 HTML（判断「要不要真的重绘」用，见 renderAll）。\n     * 放在闭包里而不是 DOM 属性上：整份 HTML 有几 KB，塞进 data-* 既难看又会被别处读到。\n     */\n    let lastRenderedHtml = ''\n\n    function renderAll(container) {\n      panelEl = container\n      const html = state.editor ? renderEditorHtml() : renderMainHtml()\n      /*\n       * 内容没变就**别碰 DOM**。\n       *\n       * 整块 `innerHTML = …` 会把所有节点重建一遍：滚动位置跳回顶部、hover / 焦点全丢。\n       * 而保存后有一段轮询（见 reloadUntilSettled），每 600ms 一次整块重建 = 肉眼可见的\n       * 「点一下卡片在闪」（2026-10-25 实测反馈）。这里记一份上次渲染的 HTML，逐字相同就跳过；\n       * 真变了（状态徽标 / 工具数 / 行集）才重绘一次。\n       */\n      if (lastRenderedHtml === html) {\n        renderToast()\n        return\n      }\n      /*\n       * 整块重建会把列表的滚动位置清零（`.mX_list` 是独立滚动容器）。先记下来、重建完放回去——\n       * 试连已经改成原地更新（见 refreshTestPanel），但保存 / 刷新 / 行集变化仍会走整块重绘，\n       * 不还原就会「滚到某一行操作一下、界面跳回顶部」。\n       */\n      const listBefore = container.querySelector('.mX_list')\n      const listScrollTop = listBefore === null ? 0 : listBefore.scrollTop\n      lastRenderedHtml = html\n      container.innerHTML = html\n      const listAfter = container.querySelector('.mX_list')\n      if (listAfter !== null && listScrollTop > 0) listAfter.scrollTop = listScrollTop\n      bindEditorEvents(container)\n      renderToast()\n    }\n\n    function renderToast() {\n      if (toastEl === undefined || !toastEl.isConnected) {\n        toastEl = document.createElement('div')\n        toastEl.className = 'mX_toast'\n        document.body.appendChild(toastEl)\n      }\n      if (state.toast) {\n        toastEl.textContent = state.toast\n        toastEl.dataset.kind = state.toastKind\n        toastEl.style.display = ''\n      } else {\n        toastEl.style.display = 'none'\n      }\n    }\n\n    function badge(text, kind, cls) {\n      return '<span class=\"mX_badge' + (cls ? ' ' + cls : '') + '\"' + (kind ? ' data-status=\"' + kind + '\"' : '') + '>' + esc(text) + '</span>'\n    }\n\n    function transportBadge(transport) {\n      return badge(transport === 'stdio' ? 'stdio' : 'http', '', '')\n    }\n\n    function summaryOf(server) {\n      const config = server.config || {}\n      if (config.transport === 'stdio') {\n        const command = (config.command || '') + (config.args && config.args.length ? ' ' + config.args.join(' ') : '')\n        return config.cwd ? config.cwd + ' $ ' + command : command\n      }\n      return config.url || ''\n    }\n\n    function statusBadge(status) {\n      return badge(STATUS_TEXT[status] || status, STATUS_KIND[status] || '')\n    }\n\n    /**\n     * 徽标显示哪一态：平时用**观测态**（`server.status`，loader 说了算）。\n     *\n     * 只有「刚保存、正在等 HMR 收敛」的那一两秒（`state.settling`）改按文件里的**期望态**\n     * （`server.disabled`）渲染：保存早就成功了，但宿主重读补丁层、重挂 mcp-client 有 1~2 秒\n     * 延迟，这期间徽标若继续写「运行中」，用户会以为「点了没反应」（2026-10-25 实测反馈）。\n     * 收敛窗口一结束就回到观测态——宿主真的没重载成功时，界面上不会留下一个骗人的「已停用」。\n     */\n    function displayStatus(server) {\n      if (!state.settling) return server.status\n      if (server.disabled === true) return 'disabled'\n      return server.status === 'disabled' ? 'loading' : server.status\n    }\n\n    /**\n     * 「运行中但一个工具都没有」按**未连接**显示。\n     *\n     * 为什么不只看 `status`：mcp-client 连不上时 apply 照样 resolve（`failOnStartupError` 默认\n     * false），fiber 还是 active——只看它就会显示「运行中」，可服务器一个工具都没有。工具是\n     * 「连接成功 + tools/list」之后唯一会留下的产物，所以 active 且 0 个工具就是没连上。\n     * `toolCount === undefined`（宿主读不到注册表）**不猜**；停用的行也不叠加。\n     */\n    function notConnected(server) {\n      return server.status === 'active' && server.disabled !== true && server.toolCount === 0\n    }\n\n    /** 状态槽位的 HTML（渲染与原地同步共用同一判据，否则两处迟早不一致）。 */\n    function statusSlotHtml(server) {\n      return notConnected(server) ? badge(t('list.notConnected'), 'warn', '') : statusBadge(displayStatus(server))\n    }\n\n\n    /** 启停按钮文案（渲染与原地同步共用）。 */\n    function toggleLabel(server) {\n      return server.disabled ? t('btn.enable') : t('btn.disable')\n    }\n\n    /**\n     * 只同步「会随宿主变化的那几个点」，**不重建 DOM**。\n     *\n     * 为什么需要它：整块 `innerHTML = …` 会把列表里所有节点重建一遍（滚动跳、hover / 焦点丢），\n     * 而点一次启停、等宿主 HMR 收敛的那几秒里状态会变两三次——逐次整块重绘就是用户看到的\n     * 「点一下就闪」（2026-10-25 实测反馈）。这里改成只改状态徽标、工具数与启停文案；\n     * 只有**结构性**变化（增删行、编辑器开关）才回落整块重绘。\n     */\n    function syncLiveState() {\n      if (panelEl === undefined || panelEl === null) return\n      if (state.editor !== null) {\n        refresh()\n        return\n      }\n      const cards = [...panelEl.querySelectorAll('.mX_card[data-id]')]\n      if (cards.length !== state.servers.length) {\n        refresh()\n        return\n      }\n      const byId = new Map(cards.map((card) => [card.getAttribute('data-id'), card]))\n      for (const server of state.servers) {\n        const card = byId.get(server.id)\n        if (card === undefined) {\n          refresh()\n          return\n        }\n        const statusSlot = card.querySelector('[data-role=\"status\"]')\n        if (statusSlot !== null) statusSlot.innerHTML = statusSlotHtml(server)\n        const toolSlot = card.querySelector('[data-role=\"toolCount\"]')\n        if (toolSlot !== null) toolSlot.textContent = toolCountText(server)\n        const toggle = card.querySelector('[data-role=\"toggle\"]')\n        if (toggle !== null) toggle.textContent = toggleLabel(server)\n      }\n      renderToast()\n    }\n\n    /**\n     * 已知工具数的合计（列表上方成本提示用）。\n     *\n     * 口径与 `scripts/mcp-tool-budget.mjs` 的 `summarizeServers` 逐条对齐：\n     *   · 停用的行不注册工具 → 不计入；\n     *   · `toolCount === undefined` = 宿主读不到注册表（或该行没连上）→ **不当作 0**，也不计入。\n     *\n     * 注意这里**没有阈值常量**：阈值由宿主下发（DTO 的 `toolBudget`，宿主侧 `AGENT_TOOL_BUDGET`），\n     * 客户端只负责比较——写死一个 80 就是同一件事的第二份真相，换阈值时两边必漂。\n     */\n    function knownToolTotal(servers) {\n      let total = 0\n      for (const server of servers) {\n        if (server.disabled === true) continue\n        if (typeof server.toolCount !== 'number' || !Number.isFinite(server.toolCount)) continue\n        total += server.toolCount\n      }\n      return total\n    }\n\n    /** 行上的工具数文案：缺失显示「未知」而不是 0（缺失是「读不到」，不是「没有」）。 */\n    function toolCountText(server) {\n      return typeof server.toolCount === 'number' && Number.isFinite(server.toolCount)\n        ? t('list.toolsCount', { count: server.toolCount })\n        : t('list.toolsUnknown')\n    }\n\n    /**\n     * 「外部占用」脚注：本卡之外还挂着哪些 mcp-client（别的插件自管的行）。\n     *\n     * 三处刻意与真冲突拉开距离，因为**两者不是一回事**（issue #5 的教训）：\n     * 判据不同（这是清单本身，不与托管行求交集；冲突是清单 ∩ 托管行）、颜色不同（中性灰 vs 黄）、\n     * 位置不同（列表下方脚注 vs 列表上方横幅）。零重名时它照样显示——它说的是「这些名字被占了」，\n     * 不是「你重名了」。**只有真重名才该报警**。\n     *\n     * 名字逐个渲染成 chip，并把**托管它的 loader 行 id** 放进 title：只给一个 serverName 时，\n     * 用户看不出它打哪来（`codegraph` 这种名字尤其像本卡自己的）。\n     */\n    function renderExternalNoteHtml() {\n      const list = state.externalServers || []\n      if (list.length === 0) return ''\n      const chips = list.map((item) => '<span class=\"mX_noteName\" title=\"' + esc(item.id) + '\">' + esc(item.serverName) + '</span>').join('')\n      return '<div class=\"mX_note\" title=\"' + esc(t('banner.externalOccupiedHint')) + '\">'\n        + '<i class=\"mX_noteGlyph\">i</i>'\n        + '<span>' + esc(t('banner.externalOccupied')) + '</span>'\n        + chips\n        + '</div>'\n    }\n\n    function renderMainHtml() {\n      const parts = []\n      parts.push('<div class=\"mX_panel\">')\n      parts.push('<div class=\"mX_panelHeader\"><h2 class=\"mX_panelTitle\">' + t('panel.title') + '</h2>')\n      parts.push('<span class=\"mX_subtitle\" title=\"' + esc(state.patchFile) + '\">' + esc(state.patchFile) + '</span>')\n      parts.push('<span class=\"mX_toolbarSpacer\"></span>')\n      parts.push('<button class=\"mX_btnGhost\" data-action=\"refresh\"' + (state.loading ? ' disabled' : '') + '>' + t('btn.refresh') + '</button>')\n      parts.push('<button class=\"mX_btn\" data-action=\"add\">' + t('btn.addServer') + '</button>')\n      parts.push('</div>')\n      if (state.fileError) parts.push('<div class=\"mX_banner\" data-kind=\"error\">' + esc(t('banner.fileError', { error: state.fileError })) + '</div>')\n      // 冲突横幅只报**真重名**（host 端的 conflicts 已与托管行求过交集）：一条都不相交时\n      // 这里什么都不渲染——曾经把「外部实例清单」原样当冲突渲染，于是不重名也常驻报警（issue #5）。\n      // 整句也必须 `esc()` 包住：文案里有 `mcp__<serverName>__*`，不转义时 `<serverName>` 会被\n      // innerHTML 当成一个未知标签吃掉，用户在界面上看到的是 `mcp____*`（见文件头「带 < 的文案\n      // 一律 esc 包住」那条约定——这里当初漏了，缺陷只在**真有冲突**时才可见，所以一直没被发现）。\n      if (state.conflicts && state.conflicts.length) {\n        parts.push('<div class=\"mX_banner\" data-kind=\"warn\">' + esc(t('banner.conflicts', { names: state.conflicts.map((c) => c.serverName).join(t('list.separator')) })) + '</div>')\n      }\n      // 成本可见：MCP 工具的数量不由本仓决定，阈值也由宿主下发（DTO 的 toolBudget）——客户端\n      // 只比较、不留第二份数字。老宿主不下发就没有阈值，宁可不提示也不写死一个 80。\n      const toolTotal = knownToolTotal(state.servers)\n      if (!state.loading && typeof state.toolBudget === 'number' && toolTotal > state.toolBudget) {\n        parts.push('<div class=\"mX_banner\" data-kind=\"warn\">' + esc(t('list.agentBudget', { total: toolTotal, budget: state.toolBudget })) + '</div>')\n      }\n      // 外部占用**不在这里**渲染：它是信息不是告警，放在列表下方当脚注（renderExternalNoteHtml），\n      // 免得一条「不重名也常驻」的蓝框顶在列表前面被读成报错。\n      parts.push('<div class=\"mX_list\">')\n      // 「加载中」只在整个列表还空着时占位：已经有行时刷新仍显示旧列表（按钮已置灰），\n      // 否则内容高度会瞬间塌掉，滚动位置跟着归零——那正是「点刷新跳回顶部」的另一半原因。\n      if (state.loading && state.servers.length === 0) {\n        parts.push('<div class=\"mX_loading\">' + t('list.loading') + '</div>')\n      } else if (state.servers.length === 0) {\n        parts.push('<div class=\"mX_empty\">' + esc(t('list.empty')) + '<br>' + esc(t('list.emptyHint')) + '<br><br>' + esc(t('list.emptyReload')) + '</div>')\n      } else {\n        for (const server of state.servers) parts.push(renderCardHtml(server))\n      }\n      parts.push('</div>')\n      parts.push(renderExternalNoteHtml())\n      // 试连结果单独占一个槽：`runTest()` 只换这一块，不整块重绘（见 refreshTestPanel）。\n      parts.push('<div class=\"mX_testPanel\" data-role=\"testPanel\">' + (state.test ? renderTestHtml() : '') + '</div>')\n      parts.push('<div class=\"mX_banner\" data-kind=\"info\">' + t('msg.hotReload') + '</div>')\n      parts.push('</div>')\n      return parts.join('')\n    }\n\n    function renderCardHtml(server) {\n      const parts = []\n      // `data-id` + 三个 `data-role` 槽位是给 `syncLiveState()` 用的：状态 / 工具数 / 启停文案会\n      // 随宿主变化，那些变化**不必重建整张卡**（重建就是「闪」），原地改这几个点就够。\n      parts.push('<div class=\"mX_card\" data-id=\"' + esc(server.id) + '\">')\n      parts.push('<div class=\"mX_cardRow\">')\n      parts.push(transportBadge(server.transport))\n      parts.push('<span class=\"mX_cardName\">' + esc(server.serverName) + '</span>')\n      parts.push('<span data-role=\"status\">' + statusSlotHtml(server) + '</span>')\n      if (server.conflict) parts.push(badge(t('list.conflict'), 'warn', ''))\n      parts.push('<span class=\"mX_cardActions\">')\n      parts.push('<button class=\"mX_linkBtn\" data-action=\"test\" data-id=\"' + esc(server.id) + '\"' + (state.busy ? ' disabled' : '') + '>' + t('btn.test') + '</button>')\n      parts.push('<button class=\"mX_linkBtn\" data-action=\"edit\" data-id=\"' + esc(server.id) + '\"' + (state.busy ? ' disabled' : '') + '>' + t('btn.edit') + '</button>')\n      parts.push('<button class=\"mX_linkBtn\" data-action=\"toggle\" data-role=\"toggle\" data-id=\"' + esc(server.id) + '\"' + (state.busy ? ' disabled' : '') + '>' + toggleLabel(server) + '</button>')\n      // 危险动作与上面三个安全动作之间隔一条发丝线：靠位置分组，不靠换样式（删除必须用官方\n      // danger 配方，见脚本检查十一）。\n      parts.push('<span class=\"mX_actionSep\" aria-hidden=\"true\"></span>')\n      parts.push('<button class=\"mX_btnGhost mX_btnDanger\" data-action=\"remove\" data-id=\"' + esc(server.id) + '\"' + (state.busy ? ' disabled' : '') + '>' + t('btn.remove') + '</button>')\n      parts.push('</span>')\n      parts.push('</div>')\n      parts.push('<div class=\"mX_cardSummary\" title=\"' + esc(summaryOf(server)) + '\">' + esc(summaryOf(server)) + '</div>')\n      // 该行贡献的工具数：成本信息，单独一行（次级色）。\n      parts.push('<div class=\"mX_metaRow\">')\n      parts.push('<span class=\"mX_toolCount\" data-role=\"toolCount\" title=\"' + esc(t('list.toolsCountHint')) + '\">' + esc(toolCountText(server)) + '</span>')\n      parts.push('</div>')\n      parts.push('</div>')\n      return parts.join('')\n    }\n\n    function renderTestHtml() {\n      const test = state.test\n      const parts = []\n      parts.push('<div class=\"mX_toolWrap\">')\n      if (test.running) {\n        parts.push('<div class=\"mX_banner\" data-kind=\"info\"><span class=\"mX_spinner\"></span> ' + t('msg.testConnecting') + '</div>')\n      } else {\n        const result = test.result || {}\n        parts.push(result.ok ? '<div class=\"mX_banner\" data-kind=\"ok\">' + t('msg.testOk') + '</div>' : '<div class=\"mX_banner\" data-kind=\"error\">' + t('msg.testFailed', { error: esc(result.error || t('error.unknown')) }) + '</div>')\n        const meta = []\n        if (result.durationMs !== undefined) meta.push(t('msg.metaDuration', { ms: result.durationMs }))\n        if (result.protocolVersion) meta.push(t('msg.metaProtocol', { version: result.protocolVersion }))\n        if (result.serverInfo && (result.serverInfo.name || result.serverInfo.version)) meta.push(t('msg.metaServer', { name: [result.serverInfo.name, result.serverInfo.version].filter(Boolean).join(' ') }))\n        meta.push(t('msg.metaTools', { count: result.toolsCount || 0 }))\n        parts.push('<div class=\"mX_toolHeader\">' + esc(meta.join(' · ')) + '</div>')\n        if (result.ok && result.tools && result.tools.length) {\n          parts.push('<div class=\"mX_toolList\">')\n          for (const tool of result.tools) {\n            parts.push('<div class=\"mX_toolItem\"><span class=\"mX_toolName\">mcp__' + esc(test.serverName) + '__' + esc(tool.name) + '</span>')\n            if (tool.description) parts.push('<span class=\"mX_toolDesc\">' + esc(String(tool.description).slice(0, 200)) + '</span>')\n            parts.push('</div>')\n          }\n          parts.push('</div>')\n        }\n      }\n      parts.push('</div>')\n      return parts.join('')\n    }\n\n    /* ================================ 渲染：编辑表单 ================================ */\n\n    function kvToText(map) {\n      if (!map) return ''\n      return Object.entries(map).map((pair) => pair[0] + '=' + pair[1]).join('\\n')\n    }\n\n    function renderEditorHtml() {\n      const editor = state.editor\n      const server = editor.server\n      const config = (server && server.config) || {}\n      const title = editor.mode === 'create' ? t('panel.editorCreate') : t('panel.editorEdit')\n      const transport = config.transport || 'stdio'\n      const reconnect = config.reconnect || {}\n      const parts = []\n      parts.push('<div class=\"mX_panel\">')\n      parts.push('<div class=\"mX_panelHeader\"><h2 class=\"mX_panelTitle\">' + esc(title) + '</h2></div>')\n      parts.push('<div class=\"mX_modalBody\">')\n      parts.push('<div class=\"mX_formRow\">')\n      parts.push('<div class=\"mX_field\"><label class=\"mX_fieldLabel\" for=\"ed_name\">' + esc(t('panel.fieldName')) + '</label><input class=\"mX_input\" id=\"ed_name\" placeholder=\"' + esc(t('placeholder.serverName')) + '\" value=\"' + esc(config.serverName || '') + '\"><p class=\"mX_fieldError\" id=\"ed_nameError\"></p></div>')\n      parts.push('<div class=\"mX_field\"><span class=\"mX_fieldLabel\">' + esc(t('panel.fieldTransport')) + '</span><span class=\"mX_radioRow\">')\n      parts.push('<label class=\"mX_radioLabel\"><input type=\"radio\" name=\"ed_transport\" value=\"stdio\"' + (transport === 'stdio' ? ' checked' : '') + '>' + esc(t('panel.transportStdio')) + '</label>')\n      parts.push('<label class=\"mX_radioLabel\"><input type=\"radio\" name=\"ed_transport\" value=\"streamable-http\"' + (transport === 'streamable-http' ? ' checked' : '') + '>' + esc(t('panel.transportHttp')) + '</label>')\n      parts.push('</span></div>')\n      parts.push('</div>')\n      parts.push('<div id=\"ed_stdio\" style=\"display:' + (transport === 'stdio' ? 'flex' : 'none') + ';flex-direction:column;gap:10px\">')\n      parts.push('<div class=\"mX_formRow\">')\n      parts.push('<div class=\"mX_field\"><label class=\"mX_fieldLabel\" for=\"ed_command\">' + esc(t('panel.fieldCommand')) + '</label><input class=\"mX_input\" id=\"ed_command\" placeholder=\"npx\" value=\"' + esc(config.command || '') + '\"></div>')\n      parts.push('<div class=\"mX_field\"><label class=\"mX_fieldLabel\" for=\"ed_cwd\">' + esc(t('panel.fieldCwd')) + '</label><input class=\"mX_input\" id=\"ed_cwd\" placeholder=\"/path/to/project\" value=\"' + esc(config.cwd || '') + '\"></div>')\n      parts.push('</div>')\n      parts.push('<div class=\"mX_field\"><label class=\"mX_fieldLabel\" for=\"ed_args\">' + esc(t('panel.fieldArgs')) + '</label><textarea class=\"mX_input mX_textarea\" id=\"ed_args\" placeholder=\"[-y, @modelcontextprotocol/server-filesystem]\">' + esc(JSON.stringify(config.args || [])) + '</textarea></div>')\n      parts.push('<div class=\"mX_field\"><label class=\"mX_fieldLabel\" for=\"ed_env\">' + esc(t('panel.fieldEnv')) + '</label><textarea class=\"mX_input mX_textarea\" id=\"ed_env\" placeholder=\"GITHUB_TOKEN=js:process.env.GITHUB_TOKEN\">' + esc(kvToText(config.env)) + '</textarea></div>')\n      parts.push('</div>')\n      parts.push('<div id=\"ed_http\" style=\"display:' + (transport === 'streamable-http' ? 'flex' : 'none') + ';flex-direction:column;gap:10px\">')\n      parts.push('<div class=\"mX_field\"><label class=\"mX_fieldLabel\" for=\"ed_url\">' + esc(t('panel.fieldUrl')) + '</label><input class=\"mX_input\" id=\"ed_url\" placeholder=\"http://localhost:3000/mcp\" value=\"' + esc(config.url || '') + '\"></div>')\n      parts.push('<div class=\"mX_field\"><label class=\"mX_fieldLabel\" for=\"ed_headers\">' + esc(t('panel.fieldHeaders')) + '</label><textarea class=\"mX_input mX_textarea\" id=\"ed_headers\" placeholder=\"Authorization=js:process.env.MCP_TOKEN\">' + esc(kvToText(config.headers)) + '</textarea></div>')\n      parts.push('</div>')\n      parts.push('<div class=\"mX_formRow\">')\n      parts.push('<div class=\"mX_field\"><label class=\"mX_fieldLabel\" for=\"ed_timeout\">toolCallTimeoutMs</label><input class=\"mX_input\" id=\"ed_timeout\" type=\"number\" min=\"1\" value=\"' + esc(String(config.toolCallTimeoutMs ?? 60000)) + '\"></div>')\n      parts.push('<label class=\"mX_checkRow\" style=\"padding-top:18px\"><input type=\"checkbox\" id=\"ed_failStartup\"' + (config.failOnStartupError ? ' checked' : '') + '>' + esc(t('panel.fieldFailOnStartupError')) + '</label>')\n      parts.push('<label class=\"mX_checkRow\" style=\"padding-top:18px\"><input type=\"checkbox\" id=\"ed_enabled\"' + (server && server.disabled ? '' : ' checked') + '>' + esc(t('panel.fieldEnabled')) + '</label>')\n      parts.push('</div>')\n      parts.push('<div class=\"mX_formRow\" style=\"align-items:end\">')\n      parts.push('<label class=\"mX_checkRow\" style=\"padding-top:18px\"><input type=\"checkbox\" id=\"ed_rcEnabled\"' + (reconnect.enabled !== false ? ' checked' : '') + '>' + esc(t('panel.fieldReconnect')) + '</label>')\n      parts.push('<div class=\"mX_field\"><label class=\"mX_fieldLabel\" for=\"ed_rcInitial\">initialDelayMs</label><input class=\"mX_input\" id=\"ed_rcInitial\" type=\"number\" min=\"1\" value=\"' + esc(String(reconnect.initialDelayMs ?? 500)) + '\"></div>')\n      parts.push('<div class=\"mX_field\"><label class=\"mX_fieldLabel\" for=\"ed_rcMax\">maxDelayMs</label><input class=\"mX_input\" id=\"ed_rcMax\" type=\"number\" min=\"1\" value=\"' + esc(String(reconnect.maxDelayMs ?? 30000)) + '\"></div>')\n      parts.push('<div class=\"mX_field\"><label class=\"mX_fieldLabel\" for=\"ed_rcAttempts\">maxAttempts</label><input class=\"mX_input\" id=\"ed_rcAttempts\" type=\"number\" min=\"1\" value=\"' + esc(String(reconnect.maxAttempts ?? 10)) + '\"></div>')\n      parts.push('</div>')\n      parts.push('<p class=\"mX_formError\" id=\"ed_error\"></p>')\n      parts.push('<div class=\"mX_hint\">' + esc(t('panel.hint')) + '</div>')\n      // 测试结果就地展示在编辑器里（容器固定，由 testEditor 直接改 innerHTML）：\n      // 这样「测试连接 → 保存」是一条连续动作，表单与已填内容都留着\n      parts.push('<div id=\"ed_testResult\">' + (state.test ? renderTestHtml() : '') + '</div>')\n      parts.push('</div>')\n      parts.push('<div class=\"mX_modalFooter\">')\n      parts.push('<button class=\"mX_btnGhost\" data-action=\"editor-cancel\">' + t('btn.cancel') + '</button>')\n      parts.push('<button class=\"mX_btnGhost\" data-action=\"editor-test\"' + (state.busy ? ' disabled' : '') + '>' + t('btn.testConnection') + '</button>')\n      parts.push('<button class=\"mX_btn\" data-action=\"editor-save\"' + (state.busy ? ' disabled' : '') + '>' + t('btn.save') + '</button>')\n      parts.push('</div>')\n      parts.push('</div>')\n      return parts.join('')\n    }\n\n    function bindEditorEvents(container) {\n      if (!state.editor) return\n      const toggleSections = () => {\n        const stdio = container.querySelector('#ed_stdio')\n        const http = container.querySelector('#ed_http')\n        const checked = container.querySelector('input[name=\"ed_transport\"]:checked')\n        const transport = checked ? checked.value : 'stdio'\n        if (stdio) stdio.style.display = transport === 'stdio' ? 'flex' : 'none'\n        if (http) http.style.display = transport === 'streamable-http' ? 'flex' : 'none'\n      }\n      const radios = container.querySelectorAll('input[name=\"ed_transport\"]')\n      for (const radio of radios) radio.addEventListener('change', toggleSections)\n      toggleSections()\n      // serverName 一撞名就当场标红：这是「直观」的主力——用户不必先点保存、再读一条\n      // 事后错误。事件挂在 input 上而不是 blur 上，因为撞名多半是边打边发生（打到第 3 个\n      // 字符就撞上了）。开表单时先跑一次，编辑一条历史遗留的同名行也能立刻看到原因。\n      const nameInput = container.querySelector('#ed_name')\n      if (nameInput !== null) {\n        nameInput.addEventListener('input', () => validateEditorName())\n        validateEditorName()\n      }\n    }\n\n    function parseArgs(text) {\n      const trimmed = (text || '').trim()\n      if (trimmed === '') return []\n      if (trimmed.startsWith('[')) {\n        const parsed = JSON.parse(trimmed)\n        if (!Array.isArray(parsed) || parsed.some((item) => typeof item !== 'string')) throw new Error(t('error.argsNotArray'))\n        return parsed\n      }\n      return trimmed.split('\\n').map((line) => line.trim()).filter(Boolean)\n    }\n\n    function parseKvText(text) {\n      const out = {}\n      for (const raw of String(text || '').split('\\n')) {\n        const line = raw.trim()\n        if (line === '' || line.startsWith('#')) continue\n        const match = line.match(/^([A-Za-z_][A-Za-z0-9_.-]*)\\s*[:=]\\s*(.*)$/)\n        if (match === null) throw new Error(t('error.unparsableLine', { line }))\n        out[match[1]] = match[2]\n      }\n      return out\n    }\n\n    function newId() {\n      let id = 'mcp-'\n      const chars = 'abcdefghijklmnopqrstuvwxyz0123456789'\n      if (window.crypto && crypto.randomUUID) {\n        id = 'mcp-' + crypto.randomUUID().replace(/-/g, '').slice(0, 10)\n      } else {\n        for (let i = 0; i < 10; i++) id += chars[Math.floor(Math.random() * chars.length)]\n      }\n      return id\n    }\n\n    function collectEditor() {\n      const value = (id) => {\n        const input = document.getElementById(id)\n        return input ? String(input.value || '').trim() : ''\n      }\n      const checked = (id) => {\n        const input = document.getElementById(id)\n        return input ? input.checked : false\n      }\n      const config = { serverName: value('ed_name') }\n      const transportInput = document.querySelector('input[name=\"ed_transport\"]:checked')\n      config.transport = transportInput ? transportInput.value : 'stdio'\n      if (config.transport === 'stdio') {\n        config.command = value('ed_command')\n        config.args = parseArgs(document.getElementById('ed_args')?.value || '')\n        config.env = parseKvText(document.getElementById('ed_env')?.value || '')\n        const cwd = value('ed_cwd')\n        if (cwd !== '') config.cwd = cwd\n      } else {\n        config.url = value('ed_url')\n        config.headers = parseKvText(document.getElementById('ed_headers')?.value || '')\n      }\n      const timeoutText = value('ed_timeout')\n      if (timeoutText !== '') config.toolCallTimeoutMs = Number(timeoutText)\n      if (checked('ed_failStartup')) config.failOnStartupError = true\n      if (checked('ed_rcEnabled')) {\n        config.reconnect = {\n          enabled: true,\n          initialDelayMs: Number(value('ed_rcInitial') || 500),\n          maxDelayMs: Number(value('ed_rcMax') || 30000),\n          maxAttempts: Number(value('ed_rcAttempts') || 10),\n        }\n      } else {\n        config.reconnect = { enabled: false }\n      }\n      const row = { id: (state.editor.server && state.editor.server.id) || newId(), config }\n      if (!checked('ed_enabled')) row.disabled = true\n      return row\n    }\n\n    function setEditorError(message) {\n      const errorEl = document.getElementById('ed_error')\n      if (errorEl) errorEl.textContent = message || ''\n    }\n\n    /**\n     * serverName 的**字段级**实时校验：撞名当场在输入框下给原因，并把输入框标红。\n     *\n     * 它只是「一眼看见」，**不是闸门**——真正拒绝保存的是 `saveEditor()`（本地即时反馈，\n     * 见下面 externalClash 那段）与宿主侧的 `externalNameRejection()`（权威）。所以这里\n     * 刻意**不**禁用保存按钮：历史遗留的同名行要能改别的字段，而「能不能存」由那两道说。\n     *\n     * 两个判据与保存侧逐字对齐（口径分叉过一次就很难再对齐了）：\n     * ① 与本卡其它行重名 → `error.duplicateName`；\n     * ② 撞上外部实例名单 → `error.externalClash`，但**这行本来就叫这个名字**时放行。\n     */\n    function validateEditorName() {\n      const input = document.getElementById('ed_name')\n      const errorEl = document.getElementById('ed_nameError')\n      if (input === null) return ''\n      const name = String(input.value || '').trim()\n      const setError = (message) => {\n        if (errorEl !== null) errorEl.textContent = message\n        if (message === '') delete input.dataset.invalid\n        else input.dataset.invalid = 'true'\n        return message\n      }\n      const original = state.editor !== null && state.editor.server !== null ? state.editor.server : null\n      if (name === '') return setError('')\n      const selfId = original !== null ? original.id : null\n      if (state.servers.some((server) => server.id !== selfId && server.serverName === name)) {\n        return setError(t('error.duplicateName', { name }))\n      }\n      const clash = (state.externalServers || []).find((item) => item.serverName === name)\n      if (clash !== undefined && !(original !== null && original.serverName === name)) {\n        return setError(t('error.externalClash', { name, id: clash.id }))\n      }\n      return setError('')\n    }\n\n    /* ================================ 动作 ================================ */\n\n    function refresh() {\n      if (panelEl) renderAll(panelEl)\n    }\n\n    /**\n     * 只重绘**试连结果**那一块（`[data-role=\"testPanel\"]`），不整块重建。\n     *\n     * 为什么必须单开一条：试连结果渲染在卡片列表**下方**，而列表自己是可滚动的\n     * （`.mX_list`，max-height 420px）。整块 `innerHTML` 重建会把列表的滚动位置清零——用户滚到\n     * 某一行点「测试」，界面当场跳回顶部（2026-10-25 实测反馈）。这一块不在列表里，单独换它，\n     * 列表的滚动 / hover / 焦点全都留着。\n     */\n    function refreshTestPanel() {\n      if (panelEl === undefined || panelEl === null) return\n      const slot = panelEl.querySelector('[data-role=\"testPanel\"]')\n      if (slot === null) {\n        // 当前不是主视图（编辑器打开 / 还没渲染过）：退回整块重绘。\n        refresh()\n        return\n      }\n      slot.innerHTML = state.test ? renderTestHtml() : ''\n      // 缓存要跟着走：否则下一次 refresh() 会以为 HTML 变了而整块重建，又把列表滚回顶部。\n      lastRenderedHtml = state.editor ? renderEditorHtml() : renderMainHtml()\n      renderToast()\n    }\n\n    /**\n     * 把宿主 DTO 写回 state。\n     *\n     * **GET 列表与 POST 保存的响应是同一份形状**，所以两边共用这一处：保存成功后不必再发一次\n     * GET 就能拿到权威的 `servers`（宿主现算的 status / toolCount 就在里面）与 `toolBudget`。\n     */\n    function applyServersDto(body) {\n      const dto = body !== undefined && body !== null ? body : {}\n      state.servers = Array.isArray(dto.servers) ? dto.servers : []\n      state.conflicts = Array.isArray(dto.conflicts) ? dto.conflicts : []\n      state.externalServers = Array.isArray(dto.externalServers) ? dto.externalServers : []\n      // 阈值只在宿主**真的下发**时才存（缺失 = 老宿主，不是 0：0 会让每一行都报警）。\n      state.toolBudget = typeof dto.toolBudget === 'number' ? dto.toolBudget : null\n      state.fileError = dto.fileError || ''\n      state.patchFile = dto.patchFile || ''\n    }\n\n    /**\n     * 拉一次列表。\n     *\n     * `quiet` = 轮询专用：不翻 `state.loading`、不自己主动重绘（由调用方决定何时 `refresh()`）。\n     * 不安静的话，等待收敛的那几秒里每次都要「置 loading → 重绘 → 复位 → 再重绘」，按钮与整块\n     * 列表跟着抖——这正是用户看到的「闪动」。\n     */\n    async function load(options) {\n      const quiet = options !== undefined && options.quiet === true\n      if (state.loading) return\n      if (!quiet) {\n        state.loading = true\n        refresh()\n      }\n      try {\n        applyServersDto(await apiList())\n      } catch (error) {\n        state.fileError = error instanceof Error ? error.message : String(error)\n      } finally {\n        if (!quiet) {\n          state.loading = false\n          refresh()\n        }\n      }\n    }\n\n    /**\n     * 每一行的**观测态**（loader 的 fiber 状态）是否已经追上了文件里的**期望态**（`disabled`）。\n     *\n     * 两者不是一回事：保存请求把 `disabled` 写进托管区块只需要一次写盘，而 `status` 要等宿主\n     * 重读补丁层、重挂 / 卸下那条 mcp-client 条目（HMR 约 1~2 秒）才会变。中间这段时间里\n     * 「点完停用仍显示运行中」不是没生效，只是还没重载完。\n     */\n    function statusSettled() {\n      return state.servers.every((server) => {\n        if (server.disabled === true) return server.status === 'disabled'\n        /*\n         * 启用方向必须等它**真的起来**：`loading` 是过渡态（宿主还在重挂那条 mcp-client、\n         * 或还在跟 server 握手，连不上时最长要等一次连接尝试）。只判 `!== 'disabled'` 会在\n         * status 刚变成 `loading` 的那一刻就收工、此后不再轮询——徽标就冻在「加载中 / 工具 0」，\n         * 而宿主上其实早就 active 了（实测：dbx 已是 active + 25 个工具，卡片还写着加载中）。\n         */\n        return server.status !== 'disabled' && server.status !== 'loading'\n      })\n    }\n\n    /**\n     * 保存之后**轮询到收敛**，而不是等一个固定延迟再读一次。\n     *\n     * 原来是 `setTimeout(() => load(), 800)`：800ms 通常**早于** HMR 完成，于是拿到的是旧\n     * `status`，而且只读这一次——徽标就永远停在「运行中」，直到用户手动点「刷新」（2026-10-25\n     * 实测反馈）。固定改成 2s 也只是把「永远不更新」换成「在慢机器上还是不更新」，所以这里按\n     * **收敛条件**轮询（有上限：8 秒后放弃，按真实状态渲染，不假装成功）。\n     */\n    async function reloadUntilSettled(timeoutMs = 20000) {\n      state.settling = true\n      // 只原地改状态徽标 / 工具数：不重建 DOM，所以点完按钮不会有整块刷新感。\n      syncLiveState()\n      const deadline = Date.now() + timeoutMs\n      try {\n        for (;;) {\n          await load({ quiet: true })\n          syncLiveState()\n          if (statusSettled() || Date.now() >= deadline) return\n          await new Promise((resolve) => setTimeout(resolve, 600))\n        }\n      } finally {\n        state.settling = false\n        syncLiveState()\n      }\n    }\n\n    function openEditor(mode, server) {\n      state.editor = { mode, server: server || null }\n      state.test = null\n      refresh()\n    }\n\n    function closeEditor() {\n      state.editor = null\n      refresh()\n    }\n\n    async function saveEditor() {\n      let row\n      try {\n        row = collectEditor()\n      } catch (error) {\n        setEditorError(error instanceof Error ? error.message : String(error))\n        return\n      }\n      const others = state.servers.filter((server) => server.id !== row.id)\n      if (others.some((server) => server.serverName === row.config.serverName)) {\n        setEditorError(t('error.duplicateName', { name: row.config.serverName }))\n        return\n      }\n      // 外部实例同名（别的插件托管的 mcp-client，如 codegraph 归 Codegraph 插件管）：本地先拦\n      // 一道给即时反馈；宿主侧还会再拦一次（权威）。比的是**外部实例清单**（externalServers），\n      // 不是 conflicts——conflicts 只是「已经重名」的那几行，这里要拦的是任何撞上外部名单的新名字。\n      // 已经是这一行原本的名字（历史遗留）不拦，否则连它的其它字段都改不了 —— 宿主侧同样按「是否新引入」判定。\n      const clash = (state.externalServers || []).find((item) => item.serverName === row.config.serverName)\n      const original = state.editor !== null && state.editor.server !== null ? state.editor.server : null\n      if (clash !== undefined && !(original !== null && original.serverName === row.config.serverName)) {\n        setEditorError(t('error.externalClash', { name: row.config.serverName, id: clash.id }))\n        return\n      }\n      const servers = [...others, row]\n      state.busy = true\n      setEditorError('')\n      try {\n        // 响应与 GET 是同一份 DTO：先落 state 再收尾，界面立刻是保存后的样子（不用等下一次轮询）。\n        const body = await apiSave(servers)\n        applyServersDto(body)\n        notifySaved(body, t('msg.saved'))\n        state.editor = null\n        void reloadUntilSettled()\n      } catch (error) {\n        setEditorError(error instanceof Error ? error.message : String(error))\n        toast(t('msg.saveFailed', { error: error instanceof Error ? error.message : String(error) }), 'error')\n      } finally {\n        // 不重绘：`reloadUntilSettled` 的 `syncLiveState()` 会按需原地更新 / 结构变了才整块重绘。\n        state.busy = false\n      }\n    }\n\n    async function removeServer(id) {\n      const server = state.servers.find((item) => item.id === id)\n      if (server === undefined) return\n      // 删掉最后一条＝清空托管区块，确认文案要说清这一点，保存时也要显式带 clearAll\n      const last = state.servers.length === 1\n      const question = last\n        ? t('msg.confirmRemoveLast', { name: server.serverName })\n        : t('msg.confirmRemove', { name: server.serverName })\n      if (!window.confirm(question)) return\n      const servers = state.servers.filter((item) => item.id !== id)\n      /*\n       * 只置忙、**不重绘**：整块 `innerHTML` 重建就是用户看到的「点一下卡片在闪」。\n       * 请求在本机是毫秒级返回的，按钮短暂仍可点（真要连点两下，第二次会以新 state 再算一次，\n       * 结果仍然是幂等的翻转）；换来的是点完只重绘一次（收敛时那一次，且内容没变就跳过）。\n       */\n      state.busy = true\n      try {\n        const body = await apiSave(servers, { clearAll: last })\n        applyServersDto(body)\n        notifySaved(body, t('msg.deleted'))\n        void reloadUntilSettled()\n      } catch (error) {\n        toast(t('msg.removeFailed', { error: error instanceof Error ? error.message : String(error) }), 'error')\n      } finally {\n        state.busy = false\n      }\n    }\n\n    async function toggleServer(id) {\n      const servers = state.servers.map((server) => (server.id === id ? { ...server, disabled: !server.disabled } : server))\n      /*\n       * 只置忙、**不重绘**：整块 `innerHTML` 重建就是用户看到的「点一下卡片在闪」。\n       * 请求在本机是毫秒级返回的，按钮短暂仍可点（真要连点两下，第二次会以新 state 再算一次，\n       * 结果仍然是幂等的翻转）；换来的是点完只重绘一次（收敛时那一次，且内容没变就跳过）。\n       */\n      state.busy = true\n      try {\n        const body = await apiSave(servers)\n        applyServersDto(body)\n        notifySaved(body, t('msg.updated'))\n        void reloadUntilSettled()\n      } catch (error) {\n        toast(t('msg.updateFailed', { error: error instanceof Error ? error.message : String(error) }), 'error')\n      } finally {\n        state.busy = false\n      }\n    }\n\n    async function runTest(server) {\n      state.test = { serverName: server.serverName, running: true, result: null }\n      state.editor = null\n      refreshTestPanel()\n      try {\n        const body = await apiTest(server.config)\n        state.test = { serverName: server.serverName, running: false, result: body.result || {} }\n      } catch (error) {\n        state.test = { serverName: server.serverName, running: false, result: { ok: false, error: error instanceof Error ? error.message : String(error), toolsCount: 0 } }\n      }\n      refreshTestPanel()\n    }\n\n    /**\n     * 编辑器里的「测试连接」。\n     *\n     * 两条硬约束（都是实测踩出来的）：\n     *   1. **不关编辑器**——测试只是确认配置能不能连上，紧接着就要点「保存」。早先这里把\n     *      `state.editor` 置空，而编辑器是整块替换渲染（`editor ? editorHtml : mainHtml`），\n     *      于是表单连同「保存」按钮一起消失，用户看到的就是「一点测试连接，保存就没了」。\n     *   2. **不整体重渲染**——用户的输入只活在 DOM 里（渲染始终以原始 config 为源），\n     *      `refresh()` 一次就把填好的内容冲回原样。所以结果只就地写进 `#ed_testResult`，\n     *      按钮的禁用/恢复也直接改 DOM。\n     */\n    async function testEditor() {\n      let row\n      try {\n        row = collectEditor()\n      } catch (error) {\n        setEditorError(error instanceof Error ? error.message : String(error))\n        return\n      }\n      setEditorError('')\n      const setBusy = (busy) => {\n        state.busy = busy\n        for (const el of document.querySelectorAll('[data-action=\"editor-test\"], [data-action=\"editor-save\"]')) {\n          if (el instanceof HTMLButtonElement) el.disabled = busy\n        }\n      }\n      state.test = { serverName: row.config.serverName, running: true, result: null }\n      const running = document.getElementById('ed_testResult')\n      if (running !== null) running.innerHTML = renderTestHtml()\n      setBusy(true)\n      try {\n        const body = await apiTest(row.config)\n        state.test = { serverName: row.config.serverName, running: false, result: body.result || {} }\n        toast(body.result && body.result.ok ? t('msg.testOkHint') : t('msg.testFailedToast'), body.result && body.result.ok ? 'ok' : 'error')\n      } catch (error) {\n        // 请求本身失败（路由/网络）：清掉「正在连接…」，把原因写进编辑器错误行\n        state.test = null\n        setEditorError(error instanceof Error ? error.message : String(error))\n      } finally {\n        setBusy(false)\n        const host = document.getElementById('ed_testResult')\n        if (host !== null) host.innerHTML = state.test === null ? '' : renderTestHtml()\n      }\n    }\n\n    /* ================================ 事件委托 ================================ */\n\n    function handleClick(event) {\n      const target = event.target\n      if (!(target instanceof Element)) return\n      /*\n       * 作用域：只处理**自己卡片 DOM 内**的点击。\n       * 为什么必须有：prompt 卡片的按钮也用通用 `data-action`（refresh / edit / editor-save\n       * 与这里同名），不判作用域时点 prompt 的「刷新」「编辑」「保存」都会落到这里，\n       * 拿 undefined 的 id 去操作 MCP 服务器（轻则空跑；MCP 编辑态开着时会把那张表单存下去）。\n       * 2026-10-03 实测过同一类：profile 的「删除」被 prompt 的处理器接走并报错。\n       */\n      if (panelEl === undefined || !panelEl.contains(target)) return\n      const actionEl = target.closest('[data-action]')\n      if (actionEl === null || actionEl.disabled) return\n      const action = actionEl.dataset.action\n      const id = actionEl.dataset.id\n      if (action === 'refresh') load()\n      else if (action === 'add') openEditor('create')\n      else if (action === 'edit') {\n        const server = state.servers.find((item) => item.id === id)\n        if (server) openEditor('edit', server)\n      } else if (action === 'remove') removeServer(id)\n      else if (action === 'toggle') toggleServer(id)\n      else if (action === 'test') {\n        const server = state.servers.find((item) => item.id === id)\n        if (server) runTest(server)\n      } else if (action === 'editor-cancel') closeEditor()\n      else if (action === 'editor-save') saveEditor()\n      else if (action === 'editor-test') testEditor()\n    }\n\n    /* ================================ 面板宿主挂载 ================================ */\n\n    function mountDomPanel(host) {\n      if (panelEl !== undefined && panelEl.isConnected && panelEl.parentElement === host) return\n      if (panelEl !== undefined) panelEl.remove()\n      panelEl = document.createElement('div')\n      panelEl.className = 'mX_panelHost'\n      host.appendChild(panelEl)\n      renderAll(panelEl)\n    }\n\n    /* ================================ 设置卡片（React 外壳） ================================ */\n\n    const CHEVRON_PATH = 'M11.8486 5.5L11.4238 5.92383L8.69727 8.65137C8.44157 8.90706 8.21562 9.13382 8.01172 9.29785C7.79912 9.46883 7.55595 9.61756 7.25 9.66602C7.08435 9.69222 6.91565 9.69222 6.75 9.66602C6.44405 9.61756 6.20088 9.46883 5.98828 9.29785C5.78438 9.13382 5.55843 9.13382 5.30273 8.65137L2.57617 5.92383L2.15137 5.5L3 4.65137L3.42383 5.07617L6.15137 7.80273C6.42595 8.07732 6.59876 8.24849 6.74023 8.3623C6.87291 8.46904 6.92272 8.47813 6.9375 8.48047C6.97895 8.48703 7.02105 8.48703 7.0625 8.48047C7.07728 8.47813 7.12709 8.46904 7.25977 8.3623C7.40124 8.24849 7.57405 8.07732 7.84863 7.80273L10.5762 5.07617L11 4.65137L11.8486 5.5Z'\n\n    function McpSettingsCard(props) {\n      // DSH ≥0.1.6 的插件配置页把同一条目按 view 渲染两次：summary 一句话摘要、page 完整表单。\n      // 旧版（≤0.1.5）的 settings.plugin.item 卡片不带 view，走原有可折叠卡片分支。\n      const view = props && props.view\n      const pageView = view === 'page'\n      const [open, setOpen] = React.useState(pageView)\n      const hostRef = React.useRef(null)\n      React.useEffect(() => {\n        if (!open) return\n        const host = hostRef.current\n        if (host === null) return\n        mountDomPanel(host)\n        load()\n      }, [open])\n      if (view === 'summary') {\n        return t('card.desc')\n      }\n\n      // page 视图：新页面自己画标题/图标/面包屑，这里只交表单本体，不渲染卡片头。\n      return jsxs(pageView ? 'div' : 'li', {\n        className: pageView ? 'mX_pageHost' : (open ? 'mX_pluginCard mX_pluginCardOpen' : 'mX_pluginCard'),\n        children: [\n          pageView ? null : jsxs('button', {\n            type: 'button',\n            className: 'mX_cardHeader',\n            'aria-expanded': open,\n            onClick: () => setOpen((current) => !current),\n            children: [\n              jsxs('span', {\n                className: 'mX_cardHeadText',\n                children: [\n                  jsx('span', { className: 'mX_cardName', children: t('card.name') }),\n                  jsx('span', { className: 'mX_cardDescription', children: t('card.desc') }),\n                ],\n              }),\n              jsx('span', { className: 'dshkit_badge', children: 'Kit' }),\n              jsx('svg', {\n                width: '14',\n                height: '14',\n                viewBox: '0 0 14 14',\n                fill: 'none',\n                xmlns: 'http://www.w3.org/2000/svg',\n                className: 'mX_chevron',\n                children: jsx('path', { d: CHEVRON_PATH, fill: 'currentColor' }),\n              }),\n            ],\n          }),\n          (pageView || open) ? jsx('div', {\n            className: 'mX_cardBody',\n            children: jsx('div', { ref: hostRef, className: 'mX_cardHost' }),\n          }) : null,\n        ],\n      })\n    }\n\n    /* ================================ 插件入口 ================================ */\n\n    exports.inject = ['slots']\n\n    /**\n     * DSH ≥0.1.6-alpha.2 的行配置 key：`<bundle 包名>#<行 id>`，行 id 取自 bundle 的\n     * cordis.patch.yml。独立安装时 bundle 是本包，装全家桶时是 @hyzyn/dsh-all —— 两个都注册，\n     * 未命中的那个只是躺在 ledger 里，不会渲染。\n     */\n    const ROW_CONFIG_KEYS = [\n      '@hyzyn/dsh-mcp#mcp-config',\n      '@hyzyn/dsh-all#mcp-config',\n    ]\n\n    exports.apply = (ctx) => {\n      installI18n(ctx)\n      ctx.effect(() => {\n        ensureStyle()\n        // 面板 DOM 点击委托：挂在 document 上，避免随重渲染丢失\n        document.addEventListener('click', handleClick, true)\n        return () => {\n          document.removeEventListener('click', handleClick, true)\n          styleEl?.remove()\n          styleEl = undefined\n          toastEl?.remove()\n          toastEl = undefined\n          panelEl?.remove()\n          panelEl = undefined\n        }\n      })\n      // 注册到官方插件配置 → 可配置 卡片列表（与终端 / Agent 循环 / 网页搜索同级）\n      /*\n       * 设置面：0.2.0-rc.1 起挂 `plugins.bundle.config`——key 是 **bundle 包名**，管理器的插件\n       * 详情页把它渲染在「说明」正下方；`plugins.row.config` 是 per-row 的「>」子页。\n       *\n       * 两条硬约束（第一条踩过坑，见下）：\n       *   ① `plugins.bundle.config` 的 key 是**共享命名空间**：同一个 key 只能有一个注册者，\n       *      重复注册**直接抛错**（`keyed slot ... already has an entry`），而客户端 `apply`\n       *      抛错 = 整个插件起不来（实测：把 `@hyzyn/dsh-all` 也挂上时，八个插件抢同一个 key，\n       *      启动页直接变「Failed to load plugins」）（D158）。聚合包 `@hyzyn/dsh-all` 是所有插件共用的\n       *      bundle，**不能**挂 bundle.config —— 它没有内联位，设置面走它自己的 row 入口。\n       *   ② 内联位可用时，**本包自己的** bundle 不再注册 row 槽（同一份表单两个入口会让人以为\n       *      有两套设置）；聚合包那份 row 入口**保留**（那是它在聚合安装下的唯一入口）。旧宿主\n       *      （bundle 槽不存在，0.1.6 线）回退注册全部 row 槽，功能一点不减。\n       * 就绪顺序不敏感：任一侧先到都收敛到「内联优先」（后到的本包 row 注册会被撤掉）。\n       */\n      const AGGREGATE_BUNDLE = '@hyzyn/dsh-all'\n      const BUNDLE_NAMES = [...new Set(ROW_CONFIG_KEYS.map((key) => key.split('#')[0]))]\n      const OWN_BUNDLE = BUNDLE_NAMES.find((name) => name !== AGGREGATE_BUNDLE)\n      let bundleConfigLive = false\n      const disposeOwnRowConfigs = []\n      if (OWN_BUNDLE !== undefined) {\n        ctx.slots.inject('plugins.bundle.config', () => {\n          bundleConfigLive = true\n          while (disposeOwnRowConfigs.length > 0) {\n            const disposeRow = disposeOwnRowConfigs.pop()\n            if (typeof disposeRow === 'function') disposeRow()\n          }\n          return ctx.slots.register({\n            name: 'plugins.bundle.config',\n            key: OWN_BUNDLE,\n          }, McpSettingsCard)\n        })\n      }\n      for (const key of ROW_CONFIG_KEYS) {\n        ctx.slots.inject('plugins.row.config', () => {\n          const own = key.split('#')[0] === OWN_BUNDLE\n          if (own && bundleConfigLive) return undefined\n          const disposeRow = ctx.slots.register({\n            name: 'plugins.row.config',\n            key,\n          }, McpSettingsCard)\n          if (own) disposeOwnRowConfigs.push(disposeRow)\n          return disposeRow\n        })\n      }\n      // DSH ≥0.1.6：设置里与「通用设置」平级的「插件配置」页（子 slot 由\n      // @hyzyn/dsh-kit-settings 声明）。不传 view，卡片走各自原有的可折叠形态。\n      ctx.slots.inject('settings.kit.item', () => ctx.slots.register({\n        name: 'settings.kit.item',\n        id: 'mcp-config',\n        order: 20,\n        label: () => t('card.name'),\n      }, McpSettingsCard))\n      // DSH ≤0.1.5：设置 → 插件 的「插件配置」标签页，keyed 插槽按 settings 命名空间派发。\n      ctx.slots.inject('settings.plugin.item', () => ctx.slots.register({\n        name: 'settings.plugin.item',\n        // settings.plugin.item 是 keyed 插槽：key 必须是该卡片所编辑的 settings 命名空间\n        key: 'mcp-config',\n        order: 96,\n      }, McpSettingsCard))\n    }\n\n    return exports\n  },\n})\n"
